import java.io.*;
import java.util.*;

class Main {

    // ---------- begin Matrix ----------
    public interface SemiRing<R> {
        R zero();
        R one();
        R add(R other);
        R mul(R other);
        R sub(R other);
    }

    public static class SquareMatrix<R extends SemiRing<R>> {
        int size;
        R[] buf;

        @SuppressWarnings("unchecked")
        public SquareMatrix(int size, R zero) {
            this.size = size;
            this.buf = (R[]) new SemiRing[size * size];
            for (int i = 0; i < size * size; i++) {
                this.buf[i] = zero.zero();
            }
        }

        public static <R extends SemiRing<R>> SquareMatrix<R> zero(int size, R zero) {
            return new SquareMatrix<>(size, zero);
        }

        public static <R extends SemiRing<R>> SquareMatrix<R> identity(int size, R one) {
            SquareMatrix<R> e = zero(size, one);
            for (int i = 0; i < size; i++) {
                e.buf[i * size + i] = one.one();
            }
            return e;
        }

        public R get(int x, int y) {
            if (!(x < size && y < size)) throw new AssertionError();
            return buf[x * size + y];
        }

        public void set(int x, int y, R val) {
            if (!(x < size && y < size)) throw new AssertionError();
            buf[x * size + y] = val;
        }

        public SquareMatrix<R> matadd(SquareMatrix<R> rhs) {
            if (this.size != rhs.size) throw new AssertionError();
            @SuppressWarnings("unchecked")
            R[] nb = (R[]) new SemiRing[size * size];
            for (int i = 0; i < buf.length; i++) {
                nb[i] = buf[i].add(rhs.buf[i]);
            }
            SquareMatrix<R> res = new SquareMatrix<>(size, buf[0].zero());
            res.buf = nb;
            return res;
        }

        public SquareMatrix<R> matsub(SquareMatrix<R> rhs) {
            if (this.size != rhs.size) throw new AssertionError();
            @SuppressWarnings("unchecked")
            R[] nb = (R[]) new SemiRing[size * size];
            for (int i = 0; i < buf.length; i++) {
                nb[i] = buf[i].sub(rhs.buf[i]);
            }
            SquareMatrix<R> res = new SquareMatrix<>(size, buf[0].zero());
            res.buf = nb;
            return res;
        }

        public SquareMatrix<R> matmul(SquareMatrix<R> rhs) {
            int size = this.size;
            if (size != rhs.size) throw new AssertionError();
            SquareMatrix<R> res = SquareMatrix.zero(size, buf[0].zero());
            for (int x = 0; x < size; x++) {
                for (int k = 0; k < size; k++) {
                    R a = this.get(x, k);
                    for (int y = 0; y < size; y++) {
                        R val = res.get(x, y).add(a.mul(rhs.get(k, y)));
                        res.set(x, y, val);
                    }
                }
            }
            return res;
        }

        public SquareMatrix<R> mat_pow(long n) {
            int size = this.size;
            SquareMatrix<R> t = SquareMatrix.identity(size, buf[0].one());
            SquareMatrix<R> s = this.cloneMatrix();
            long nn = n;
            while (nn > 0) {
                if ((nn & 1) == 1) {
                    t = t.matmul(s);
                }
                s = s.matmul(s);
                nn >>= 1;
            }
            return t;
        }

        public SquareMatrix<R> cloneMatrix() {
            SquareMatrix<R> res = new SquareMatrix<>(size, buf[0].zero());
            res.buf = buf.clone();
            return res;
        }
    }
    // ---------- end Matrix ----------

    // ---------- begin ModInt ----------
    public interface Modulo {
        int modulo();
    }

    public interface ConstantModulo {
        int MOD();
    }

    public static class Mod implements ConstantModulo {
        public int MOD() {
            return 1_000_000_007;
        }
    }

    public static class StaticMod implements Modulo {
        static int STATIC_MOD = 0;

        public static void set_modulo(int p) {
            STATIC_MOD = p;
        }

        public int modulo() {
            return STATIC_MOD;
        }
    }

    public static class ModInt<T extends Modulo> implements SemiRing<ModInt<T>> {
        public int v;
        public T t;

        public ModInt(int v, T t) {
            this.t = t;
            int m = t.modulo();
            this.v = v % m;
            if (this.v < 0) this.v += m;
        }

        public static <T extends Modulo> ModInt<T> new_unchecked(int d, T t) {
            ModInt<T> mi = new ModInt<>(0, t);
            mi.v = d;
            return mi;
        }

        public static <T extends Modulo> ModInt<T> zero(T t) {
            return new_unchecked(0, t);
        }

        public static <T extends Modulo> ModInt<T> one(T t) {
            return new_unchecked(1, t);
        }

        public boolean is_zero() {
            return v == 0;
        }

        public ModInt<T> pow(long n) {
            ModInt<T> tRes = one(t);
            ModInt<T> s = this;
            long nn = n;
            while (nn > 0) {
                if ((nn & 1) == 1) {
                    tRes = tRes.mul(s);
                }
                s = s.mul(s);
                nn >>= 1;
            }
            return tRes;
        }

        public ModInt<T> inv() {
            if (v == 0) throw new AssertionError();
            int m = t.modulo();
            return this.pow((long) m - 2);
        }

        public String toString() {
            return Integer.toString(v);
        }

        @Override
        public ModInt<T> zero() {
            return zero(t);
        }

        @Override
        public ModInt<T> one() {
            return one(t);
        }

        @Override
        public ModInt<T> add(ModInt<T> other) {
            int m = t.modulo();
            int d = v + other.v;
            if (d >= m) d -= m;
            return new_unchecked(d, t);
        }

        @Override
        public ModInt<T> mul(ModInt<T> other) {
            int m = t.modulo();
            long vv = (long) v * (long) other.v % m;
            return new_unchecked((int) vv, t);
        }

        @Override
        public ModInt<T> sub(ModInt<T> other) {
            int m = t.modulo();
            int d = m + v - other.v;
            if (d >= m) d -= m;
            return new_unchecked(d, t);
        }
    }

    public static long mod_pow(long r, long n, long m) {
        long t = 1 % m;
        long s = r % m;
        long nn = n;
        while (nn > 0) {
            if ((nn & 1) == 1) {
                t = t * s % m;
            }
            s = s * s % m;
            nn >>= 1;
        }
        return t;
    }
    // ---------- end ModInt ----------

    // ---------- begin Precalc ----------
    public static class Precalc<T extends Modulo> {
        ModInt<T>[] inv;
        ModInt<T>[] fact;
        ModInt<T>[] ifact;
        T t;

        @SuppressWarnings("unchecked")
        public Precalc(int n, T t) {
            this.t = t;
            inv = (ModInt<T>[]) new ModInt[n + 1];
            fact = (ModInt<T>[]) new ModInt[n + 1];
            ifact = (ModInt<T>[]) new ModInt[n + 1];
            for (int i = 0; i <= n; i++) {
                inv[i] = ModInt.one(t);
                fact[i] = ModInt.one(t);
                ifact[i] = ModInt.one(t);
            }
            for (int i = 2; i <= n; i++) {
                fact[i] = fact[i - 1].mul(ModInt.new_unchecked(i, t));
            }
            ifact[n] = fact[n].inv();
            if (n > 0) {
                inv[n] = ifact[n].mul(fact[n - 1]);
            }
            for (int i = n - 1; i >= 1; i--) {
                ifact[i] = ifact[i + 1].mul(ModInt.new_unchecked(i + 1, t));
                inv[i] = ifact[i].mul(fact[i - 1]);
            }
        }

        public ModInt<T> inv(int n) {
            if (!(n > 0)) throw new AssertionError();
            return inv[n];
        }

        public ModInt<T> fact(int n) {
            return fact[n];
        }

        public ModInt<T> ifact(int n) {
            return ifact[n];
        }

        public ModInt<T> perm(int n, int k) {
            if (k > n) {
                return ModInt.zero(t);
            }
            return fact[n].mul(ifact[n - k]);
        }

        public ModInt<T> comb(int n, int k) {
            if (k > n) {
                return ModInt.zero(t);
            }
            return fact[n].mul(ifact[k]).mul(ifact[n - k]);
        }
    }
    // ---------- end Precalc ----------

    // ---------- begin input ----------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c <= ' ') ;
            if (c == -1) return null;
            do {
                sb.append((char) c);
                c = read();
            } while (c > ' ');
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
    // ---------- end input ----------

    public static void run() throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int[] w = new int[7];
        for (int i = 0; i < 7; i++) {
            w[i] = fs.nextInt();
        }

        Mod modInstance = new Mod();
        ModInt<Mod> baseZero = ModInt.zero(modInstance);

        List<SquareMatrix<ModInt<Mod>>> mat = new ArrayList<>();
        for (int i = 1; i <= 7; i++) {
            int size = 1 << i;
            SquareMatrix<ModInt<Mod>> m = SquareMatrix.zero(size, baseZero);
            for (int j = 0; j < (1 << i); j++) {
                for (int k = 0; k < (1 << (2 * i - 1)); k++) {
                    if ((j & k) > 0) {
                        continue;
                    }
                    int next = 0;
                    for (int x = 0; x < i; x++) {
                        boolean left = x == 0 || (((k >> (i + x - 1)) & 1) == 1);
                        boolean down = ((k >> x) & 1) == 1;
                        boolean right = x == i - 1 || (((k >> (i + x)) & 1) == 1);
                        if (left && down && right) {
                            next |= 1 << x;
                        }
                    }
                    ModInt<Mod> cur = m.get(next, j);
                    m.set(next, j, cur.add(ModInt.one(modInstance)));
                }
            }
            mat.add(m);
            SquareMatrix<ModInt<Mod>> m2 = SquareMatrix.zero(size, baseZero);
            for (int j = 0; j < (1 << i); j++) {
                m2.set(j, j, ModInt.one(modInstance));
            }
            mat.add(m2);
        }

        java.util.function.BiFunction<SquareMatrix<ModInt<Mod>>, ModInt<Mod>[], ModInt<Mod>[]> mul =
                (m, b) -> {
                    int n = b.length;
                    ModInt<Mod>[] res = (ModInt<Mod>[]) new ModInt[n];
                    for (int i = 0; i < n; i++) {
                        res[i] = ModInt.zero(modInstance);
                    }
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            res[i] = res[i].add(m.get(i, j).mul(b[j]));
                        }
                    }
                    return res;
                };

        ModInt<Mod>[] b = (ModInt<Mod>[]) new ModInt[1 << 7];
        for (int i = 0; i < b.length; i++) b[i] = ModInt.zero(modInstance);

        boolean ini = false;
        for (int idx = 6; idx >= 0; idx--) {
            int i = idx;
            int wi = w[i];
            SquareMatrix<ModInt<Mod>> mat0 = mat.get(2 * i);
            SquareMatrix<ModInt<Mod>> mat1 = mat.get(2 * i + 1);
            if (!ini && wi > 0) {
                w[i] = wi - 1;
                ini = true;
                int ii = i + 1;
                for (int k = 0; k < (1 << (ii - 1)); k++) {
                    int bit = 0;
                    for (int x = 0; x < ii; x++) {
                        boolean left = x == 0 || (((k >> (x - 1)) & 1) == 1);
                        boolean down = true;
                        boolean right = x == ii - 1 || (((k >> x) & 1) == 1);
                        if (left && right && down) {
                            bit |= 1 << x;
                        }
                    }
                    b[bit] = b[bit].add(ModInt.one(modInstance));
                }
            }
            b = mul.apply(mat1, b);
            SquareMatrix<ModInt<Mod>> powMat = mat0.mat_pow(w[i]);
            b = mul.apply(powMat, b);
            int newLen = 1 << (i + 1);
            ModInt<Mod>[] nb = (ModInt<Mod>[]) new ModInt[newLen];
            for (int j = 0; j < newLen; j++) nb[j] = b[j];
            b = nb;
        }
        ModInt<Mod> ans = b[0];
        System.out.println(ans);
    }

    public static void main(String[] args) throws Exception {
        run();
    }
}

import java.io.*;
import java.util.*;

class Main {

    // ---------- begin Matrix ----------
    public interface SemiRing<R> {
        R zero();
        R one();
        R add(R a, R b);
        R mul(R a, R b);
        R sub(R a, R b);
    }

    public static class SquareMatrix<R> {
        int size;
        Object[] buf; // R[]

        public SquareMatrix(int size, R init) {
            this.size = size;
            this.buf = new Object[size * size];
            Arrays.fill(this.buf, init);
        }

        @SuppressWarnings("unchecked")
        public R get(int x, int y) {
            if (!(x < size && y < size)) throw new AssertionError();
            return (R) buf[x * size + y];
        }

        @SuppressWarnings("unchecked")
        public void set(int x, int y, R val) {
            if (!(x < size && y < size)) throw new AssertionError();
            buf[x * size + y] = val;
        }

        public static <R> SquareMatrix<R> zero(int size, SemiRing<R> sr) {
            return new SquareMatrix<>(size, sr.zero());
        }

        public static <R> SquareMatrix<R> identity(int size, SemiRing<R> sr) {
            SquareMatrix<R> e = zero(size, sr);
            for (int i = 0; i < size; i++) {
                e.set(i, i, sr.one());
            }
            return e;
        }

        public SquareMatrix<R> matadd(SquareMatrix<R> rhs, SemiRing<R> sr) {
            if (this.size != rhs.size) throw new AssertionError();
            SquareMatrix<R> res = new SquareMatrix<>(size, sr.zero());
            for (int i = 0; i < buf.length; i++) {
                @SuppressWarnings("unchecked")
                R a = (R) this.buf[i];
                @SuppressWarnings("unchecked")
                R b = (R) rhs.buf[i];
                res.buf[i] = sr.add(a, b);
            }
            return res;
        }

        public SquareMatrix<R> matsub(SquareMatrix<R> rhs, SemiRing<R> sr) {
            if (this.size != rhs.size) throw new AssertionError();
            SquareMatrix<R> res = new SquareMatrix<>(size, sr.zero());
            for (int i = 0; i < buf.length; i++) {
                @SuppressWarnings("unchecked")
                R a = (R) this.buf[i];
                @SuppressWarnings("unchecked")
                R b = (R) rhs.buf[i];
                res.buf[i] = sr.sub(a, b);
            }
            return res;
        }

        public SquareMatrix<R> matmul(SquareMatrix<R> rhs, SemiRing<R> sr) {
            int size = this.size;
            if (size != rhs.size) throw new AssertionError();
            SquareMatrix<R> res = zero(size, sr);
            for (int row = 0; row < size; row++) {
                for (int k = 0; k < size; k++) {
                    @SuppressWarnings("unchecked")
                    R a = (R) this.buf[row * size + k];
                    for (int col = 0; col < size; col++) {
                        @SuppressWarnings("unchecked")
                        R x = (R) res.buf[row * size + col];
                        @SuppressWarnings("unchecked")
                        R b = (R) rhs.buf[k * size + col];
                        res.buf[row * size + col] = sr.add(x, sr.mul(a, b));
                    }
                }
            }
            return res;
        }

        public SquareMatrix<R> mat_pow(long n, SemiRing<R> sr) {
            int size = this.size;
            SquareMatrix<R> t = identity(size, sr);
            SquareMatrix<R> s = this.cloneMatrix();
            long nn = n;
            while (nn > 0) {
                if ((nn & 1L) == 1L) {
                    t = t.matmul(s, sr);
                }
                s = s.matmul(s, sr);
                nn >>= 1;
            }
            return t;
        }

        public SquareMatrix<R> cloneMatrix() {
            SquareMatrix<R> m = new SquareMatrix<>(size, null);
            m.buf = Arrays.copyOf(this.buf, this.buf.length);
            return m;
        }
    }
    // ---------- end Matrix ----------

    // ---------- begin ModInt ----------
    public interface Modulo {
        int modulo();
    }

    public interface ConstantModulo extends Modulo {
        int MOD = 1000000007;
        default int modulo() { return MOD; }
    }

    public static class Mod implements ConstantModulo {
    }

    public static class ModInt<T extends Modulo> {
        public int v;
        public T mod;

        public ModInt(int v, T mod) {
            this.mod = mod;
            this.v = v;
        }

        public static <T extends Modulo> ModInt<T> new_unchecked(int d, T mod) {
            return new ModInt<>(d, mod);
        }

        public static <T extends Modulo> ModInt<T> zero(T mod) {
            return new ModInt<>(0, mod);
        }

        public static <T extends Modulo> ModInt<T> one(T mod) {
            return new ModInt<>(1, mod);
        }

        public boolean is_zero() {
            return v == 0;
        }

        public static <T extends Modulo> ModInt<T> newMod(int d, T mod) {
            int m = mod.modulo();
            d %= m;
            if (d < 0) d += m;
            return new ModInt<>(d, mod);
        }

        public ModInt<T> add(ModInt<T> rhs) {
            int d = this.v + rhs.v;
            int m = mod.modulo();
            if (d >= m) d -= m;
            return new ModInt<>(d, mod);
        }

        public ModInt<T> sub(ModInt<T> rhs) {
            int m = mod.modulo();
            int d = m + this.v - rhs.v;
            if (d >= m) d -= m;
            return new ModInt<>(d, mod);
        }

        public ModInt<T> mul(ModInt<T> rhs) {
            long v = (long) this.v * (long) rhs.v % (long) mod.modulo();
            return new ModInt<>((int) v, mod);
        }

        public ModInt<T> neg() {
            if (this.v == 0) return zero(mod);
            return new ModInt<>(mod.modulo() - this.v, mod);
        }

        public ModInt<T> pow(long n) {
            ModInt<T> t = one(mod);
            ModInt<T> s = new ModInt<>(this.v, mod);
            long nn = n;
            while (nn > 0) {
                if ((nn & 1L) == 1L) {
                    t = t.mul(s);
                }
                s = s.mul(s);
                nn >>= 1;
            }
            return t;
        }

        public ModInt<T> inv() {
            if (this.v == 0) throw new AssertionError();
            return this.pow(mod.modulo() - 2L);
        }

        @Override
        public String toString() {
            return Integer.toString(v);
        }
    }

    public static long mod_pow(long r, long n, long m) {
        long t = 1 % m;
        long s = r % m;
        long nn = n;
        while (nn > 0) {
            if ((nn & 1L) == 1L) {
                t = t * s % m;
            }
            s = s * s % m;
            nn >>= 1;
        }
        return t;
    }
    // ---------- end ModInt ----------

    // ---------- begin Precalc ----------
    public static class Precalc<T extends Modulo> {
        ModInt<T>[] inv;
        ModInt<T>[] fact;
        ModInt<T>[] ifact;
        T mod;

        @SuppressWarnings("unchecked")
        public Precalc(int n, T mod) {
            this.mod = mod;
            inv = (ModInt<T>[]) new ModInt[n + 1];
            fact = (ModInt<T>[]) new ModInt[n + 1];
            ifact = (ModInt<T>[]) new ModInt[n + 1];
            for (int i = 0; i <= n; i++) {
                inv[i] = ModInt.one(mod);
                fact[i] = ModInt.one(mod);
                ifact[i] = ModInt.one(mod);
            }
            for (int i = 2; i <= n; i++) {
                fact[i] = fact[i - 1].mul(ModInt.new_unchecked(i, mod));
            }
            ifact[n] = fact[n].inv();
            if (n > 0) {
                inv[n] = ifact[n].mul(fact[n - 1]);
            }
            for (int i = n - 1; i >= 1; i--) {
                ifact[i] = ifact[i + 1].mul(ModInt.new_unchecked(i + 1, mod));
                inv[i] = ifact[i].mul(fact[i - 1]);
            }
        }

        public ModInt<T> inv(int n) {
            if (!(n > 0)) throw new AssertionError();
            return inv[n];
        }

        public ModInt<T> fact(int n) {
            return fact[n];
        }

        public ModInt<T> ifact(int n) {
            return ifact[n];
        }

        public ModInt<T> perm(int n, int k) {
            if (k > n) {
                return ModInt.zero(mod);
            }
            return fact[n].mul(ifact[n - k]);
        }

        public ModInt<T> comb(int n, int k) {
            if (k > n) {
                return ModInt.zero(mod);
            }
            return fact[n].mul(ifact[k]).mul(ifact[n - k]);
        }
    }
    // ---------- end Precalc ----------

    // ---------- begin input ----------
