                return a.add(b);
            }

            @Override
            public ModInt<Mod> mul(ModInt<Mod> a, ModInt<Mod> b) {
                return a.mul(b);
            }

            @Override
            public ModInt<Mod> sub(ModInt<Mod> a, ModInt<Mod> b) {
                return a.sub(b);
            }
        };

        List<SquareMatrix<ModInt<Mod>>> mat = new ArrayList<>();
        for (int i = 1; i <= 7; i++) {
            int size = 1 << i;
            SquareMatrix<ModInt<Mod>> m = SquareMatrix.zero(size, semiRing);
            for (int j = 0; j < (1 << i); j++) {
                for (int k = 0; k < (1 << (2 * i - 1)); k++) {
                    if ((j & k) > 0) {
