                    }
                    int next = 0;
                    for (int x = 0; x < i; x++) {
                        boolean left = x == 0 || ((k >> (i + x - 1)) & 1) == 1;
                        boolean down = ((k >> x) & 1) == 1;
                        boolean right = x == i - 1 || ((k >> (i + x)) & 1) == 1;
                        if (left && down && right) {
                            next |= 1 << x;
                        }
                    }
                    ModInt<Mod> val = m.get(next, j);
                    m.set(next, j, val.add(ModInt.one(modInstance)));
                }
            }
            mat.add(m);
            SquareMatrix<ModInt<Mod>> m2 = SquareMatrix.zero(size, semiRing);
            for (int j = 0; j < (1 << i); j++) {
                m2.set(j, j, ModInt.one(modInstance));
            }
            mat.add(m2);
        }

        java.util.function.BiFunction<SquareMatrix<ModInt<Mod>>, ModInt<Mod>[], ModInt<Mod>[]> mul =
                (matrix, b) -> {
                    int n = b.length;
                    ModInt<Mod>[] res = new ModInt[n];
                    for (int i = 0; i < n; i++) {
                        res[i] = ModInt.zero(modInstance);
                    }
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            ModInt<Mod> val = matrix.get(i, j).mul(b[j]);
                            res[i] = res[i].add(val);
                        }
                    }
                    return res;
                };

        ModInt<Mod>[] b = new ModInt[1 << 7];
        for (int i = 0; i < b.length; i++) {
            b[i] = ModInt.zero(modInstance);
        }

        boolean ini = false;
        int[] ww = w.clone();

        for (int idx = 6; idx >= 0; idx--) {
            int i = idx;
            int wi = ww[i];
            List<SquareMatrix<ModInt<Mod>>> chunk = mat.subList(2 * i, 2 * i + 2);
            if (!ini && wi > 0) {
                ww[i] = wi - 1;
                ini = true;
                int ii = i + 1;
                for (int k = 0; k < (1 << (ii - 1)); k++) {
                    int bit = 0;
                    for (int x = 0; x < ii; x++) {
                        boolean left = x == 0 || ((k >> (x - 1)) & 1) == 1;
                        boolean down = true;
                        boolean right = x == ii - 1 || ((k >> x) & 1) == 1;
                        if (left && right && down) {
