    public static class Precalc<T extends Modulo> {
        ModInt<T>[] inv;
        ModInt<T>[] fact;
        ModInt<T>[] ifact;
        T t;

        @SuppressWarnings("unchecked")
        public Precalc(int n, T t) {
            this.t = t;
            inv = (ModInt<T>[]) new ModInt[n + 1];
            fact = (ModInt<T>[]) new ModInt[n + 1];
            ifact = (ModInt<T>[]) new ModInt[n + 1];
            for (int i = 0; i <= n; i++) {
                inv[i] = ModInt.one(t);
                fact[i] = ModInt.one(t);
                ifact[i] = ModInt.one(t);
            }
            for (int i = 2; i <= n; i++) {
                fact[i] = fact[i - 1].mul(ModInt.newModInt(i, t));
            }
            ifact[n] = fact[n].inv();
            if (n > 0) {
                inv[n] = ifact[n].mul(fact[n - 1]);
            }
            for (int i = n - 1; i >= 1; i--) {
                ifact[i] = ifact[i + 1].mul(ModInt.newModInt(i + 1, t));
                inv[i] = ifact[i].mul(fact[i - 1]);
            }
        }

        public ModInt<T> inv(int n) {
            if (!(n > 0)) throw new AssertionError();
            return inv[n];
        }

        public ModInt<T> fact(int n) {
            return fact[n];
        }

        public ModInt<T> ifact(int n) {
            return ifact[n];
        }

        public ModInt<T> perm(int n, int k) {
            if (k > n) return ModInt.zero(t);
            return fact[n].mul(ifact[n - k]);
        }

        public ModInt<T> comb(int n, int k) {
            if (k > n) return ModInt.zero(t);
            return fact[n].mul(ifact[k]).mul(ifact[n - k]);
        }
    }
