            while (nn > 0) {
                if ((nn & 1L) == 1L) {
                    t = t.mul(s);
                }
                s = s.mul(s);
                nn >>= 1;
            }
            return t;
        }

        public ModInt<T> inv() {
            if (this.v == 0) throw new AssertionError();
            return this.pow(mod.modulo() - 2L);
        }

        public String toString() {
            return Integer.toString(v);
        }
    }

    public static long mod_pow(long r, long n, long m) {
        long t = 1 % m;
        long s = r % m;
        long nn = n;
        while (nn > 0) {
            if ((nn & 1L) == 1L) {
                t = t * s % m;
            }
            s = s * s % m;
            nn >>= 1;
        }
        return t;
    }
