    // ---------- begin Precalc ----------
    public static class Precalc<T extends Modulo> {
        ModInt<T>[] inv;
        ModInt<T>[] fact;
        ModInt<T>[] ifact;
        T mod;

        @SuppressWarnings("unchecked")
        public Precalc(int n, T mod) {
            this.mod = mod;
            inv = (ModInt<T>[]) new ModInt[n + 1];
            fact = (ModInt<T>[]) new ModInt[n + 1];
            ifact = (ModInt<T>[]) new ModInt[n + 1];
            for (int i = 0; i <= n; i++) {
                inv[i] = ModInt.one(mod);
                fact[i] = ModInt.one(mod);
                ifact[i] = ModInt.one(mod);
            }
            for (int i = 2; i <= n; i++) {
                fact[i] = fact[i - 1].mul(ModInt.newUnchecked(i, mod));
            }
            ifact[n] = fact[n].inv();
            if (n > 0) {
                inv[n] = ifact[n].mul(fact[n - 1]);
            }
            for (int i = n - 1; i >= 1; i--) {
                ifact[i] = ifact[i + 1].mul(ModInt.newUnchecked(i + 1, mod));
                inv[i] = ifact[i].mul(fact[i - 1]);
            }
        }

        public ModInt<T> inv(int n) {
            if (!(n > 0)) throw new AssertionError();
            return inv[n];
        }

