    static Mod moduloInstance = new Mod();

    static class MSemiRing implements SemiRing<ModInt<Mod>> {
        public ModInt<Mod> zero() {
            return ModInt.zero(moduloInstance);
        }

        public ModInt<Mod> one() {
            return ModInt.one(moduloInstance);
        }

        public ModInt<Mod> add(ModInt<Mod> a, ModInt<Mod> b) {
            return a.add(b);
        }

        public ModInt<Mod> mul(ModInt<Mod> a, ModInt<Mod> b) {
            return a.mul(b);
        }

        public ModInt<Mod> sub(ModInt<Mod> a, ModInt<Mod> b) {
            return a.sub(b);
        }
    }

    static MSemiRing mSemiRing = new MSemiRing();

    public static void run() throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int[] w = new int[7];
        for (int i = 0; i < 7; i++) {
            w[i] = fs.nextInt();
        }

        List<SquareMatrix<ModInt<Mod>>> mat = new ArrayList<>();
        for (int i = 1; i <= 7; i++) {
            int size = 1 << i;
            SquareMatrix<ModInt<Mod>> m = SquareMatrix.zero(size, mSemiRing);
            for (int j = 0; j < (1 << i); j++) {
                for (int k = 0; k < (1 << (2 * i - 1)); k++) {
                    if ((j & k) > 0) {
                        continue;
                    }
                    int next = 0;
                    for (int x = 0; x < i; x++) {
                        boolean left = x == 0 || ((k >> (i + x - 1)) & 1) == 1;
                        boolean down = ((k >> x) & 1) == 1;
                        boolean right = x == i - 1 || ((k >> (i + x)) & 1) == 1;
                        if (left && down && right) {
                            next |= 1 << x;
                        }
                    }
                    ModInt<Mod> cur = m.get(next, j);
                    m.set(next, j, cur.add(ModInt.one(moduloInstance)));
                }
            }
            mat.add(m);
            SquareMatrix<ModInt<Mod>> m2 = SquareMatrix.zero(size, mSemiRing);
            for (int j = 0; j < (1 << i); j++) {
                m2.set(j, j, ModInt.one(moduloInstance));
            }
            mat.add(m2);
        }

        java.util.function.BiFunction<SquareMatrix<ModInt<Mod>>, ModInt<Mod>[], ModInt<Mod>[]> mul =
                (matrix, b) -> {
                    int n = b.length;
                    ModInt<Mod>[] res = new ModInt[n];
                    for (int i = 0; i < n; i++) {
                        res[i] = ModInt.zero(moduloInstance);
                    }
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            ModInt<Mod> val = matrix.get(i, j).mul(b[j]);
                            res[i] = res[i].add(val);
                        }
                    }
                    return res;
                };

        ModInt<Mod>[] b = new ModInt[1 << 7];
        for (int i = 0; i < b.length; i++) b[i] = ModInt.zero(moduloInstance);

        boolean ini = false;
        int[] ww = w;

        for (int idx = 6; idx >= 0; idx--) {
            int i = idx;
            int wv = ww[i];
            SquareMatrix<ModInt<Mod>> mat0 = mat.get(2 * i);
            SquareMatrix<ModInt<Mod>> mat1 = mat.get(2 * i + 1);

            if (!ini && wv > 0) {
                ww[i] = wv - 1;
                ini = true;
                int ii = i + 1;
                for (int k = 0; k < (1 << (ii - 1)); k++) {
                    int bit = 0;
                    for (int x = 0; x < ii; x++) {
                        boolean left = x == 0 || ((k >> (x - 1)) & 1) == 1;
                        boolean down = true;
                        boolean right = x == ii - 1 || ((k >> x) & 1) == 1;
                        if (left && right && down) {
                            bit |= 1 << x;
                        }
                    }
                    b[bit] = b[bit].add(ModInt.one(moduloInstance));
                }
            }

            b = mul.apply(mat1, b);
            SquareMatrix<ModInt<Mod>> powMat = mat0.mat_pow(ww[i], mSemiRing);
            b = mul.apply(powMat, b);
            int newLen = 1 << (i + 1);
            ModInt<Mod>[] nb = new ModInt[newLen];
            for (int t = 0; t < newLen; t++) nb[t] = b[t];
            b = nb;
        }

        ModInt<Mod> ans = b[0];
        System.out.println(ans);
    }

    public static void main(String[] args) throws Exception {
        run();
    }
}

