    public static class ModInt implements SemiRing<ModInt> {
        public int v;
        public static Mod moduloProvider = new Mod();

        public ModInt(int v) {
            int m = moduloProvider.modulo();
            this.v = v % m;
            if (this.v < 0) this.v += m;
        }

        public static ModInt newUnchecked(int v) {
            ModInt x = new ModInt(0);
            x.v = v;
            return x;
        }

        public ModInt zero() {
            return newUnchecked(0);
        }

        public ModInt one() {
            return newUnchecked(1);
        }

        public boolean isZero() {
            return v == 0;
        }

        public ModInt add(ModInt rhs) {
            int d = this.v + rhs.v;
            int m = moduloProvider.modulo();
            if (d >= m) d -= m;
            return newUnchecked(d);
        }

        public ModInt mul(ModInt rhs) {
            long res = (long) this.v * (long) rhs.v % (long) moduloProvider.modulo();
            return newUnchecked((int) res);
        }

        public ModInt sub(ModInt rhs) {
            int m = moduloProvider.modulo();
            int d = m + this.v - rhs.v;
            if (d >= m) d -= m;
            return newUnchecked(d);
        }

        public ModInt neg() {
            if (this.v == 0) return zero();
            return newUnchecked(moduloProvider.modulo() - this.v);
        }

        public ModInt pow(long n) {
            ModInt t = one();
            ModInt s = newUnchecked(this.v);
            long nn = n;
            while (nn > 0) {
                if ((nn & 1) == 1) {
                    t = t.mul(s);
                }
                s = s.mul(s);
                nn >>= 1;
            }
            return t;
        }

        public ModInt inv() {
            if (this.v == 0) throw new AssertionError();
            return this.pow(moduloProvider.modulo() - 2L);
        }

