            return Integer.toString(v);
        }

        public static long mod_pow(long r, long n, long m) {
            long t = 1 % m;
            long s = r % m;
            long nn = n;
            while (nn > 0) {
                if ((nn & 1) == 1) {
                    t = t * s % m;
                }
                s = s * s % m;
                nn >>= 1;
            }
            return t;
        }
    }
