        ModInt[] fact;
        ModInt[] ifact;

        public Precalc(int n) {
            inv = new ModInt[n + 1];
            fact = new ModInt[n + 1];
            ifact = new ModInt[n + 1];
            for (int i = 0; i <= n; i++) {
                inv[i] = new ModInt(1);
                fact[i] = new ModInt(1);
                ifact[i] = new ModInt(1);
            }
            for (int i = 2; i <= n; i++) {
                fact[i] = fact[i - 1].mul(ModInt.newUnchecked(i));
            }
            ifact[n] = fact[n].inv();
            if (n > 0) {
                inv[n] = ifact[n].mul(fact[n - 1]);
            }
            for (int i = n - 1; i >= 1; i--) {
                ifact[i] = ifact[i + 1].mul(ModInt.newUnchecked(i + 1));
                inv[i] = ifact[i].mul(fact[i - 1]);
            }
        }

        public ModInt inv(int n) {
            if (!(n > 0)) throw new AssertionError();
            return inv[n];
        }

        public ModInt fact(int n) {
            return fact[n];
        }

        public ModInt ifact(int n) {
            return ifact[n];
        }

        public ModInt perm(int n, int k) {
            if (k > n) return new ModInt(0);
            return fact[n].mul(ifact[n - k]);
        }

        public ModInt comb(int n, int k) {
            if (k > n) return new ModInt(0);
            return fact[n].mul(ifact[k]).mul(ifact[n - k]);
        }
