                }
            }
            mat.add(m);
            SquareMatrix<ModInt> m2 = SquareMatrix.zero(size, new ModInt(0));
            for (int j = 0; j < (1 << i); j++) {
                m2.set(j, j, new ModInt(1));
            }
            mat.add(m2);
        }

        java.util.function.BiFunction<SquareMatrix<ModInt>, ModInt[], ModInt[]> mul =
                (m, b) -> {
                    int n = b.length;
                    ModInt[] res = new ModInt[n];
                    for (int i = 0; i < n; i++) res[i] = new ModInt(0);
