                        for (int j = 0; j < n; j++) {
                            res[i] = res[i].add(m.get(i, j).mul(b[j]));
                        }
                    }
                    return res;
                };

        ModInt[] b = new ModInt[1 << 7];
        for (int i = 0; i < b.length; i++) b[i] = new ModInt(0);
        boolean ini = false;
        int[] ww = w.clone();
        for (int idx = 6; idx >= 0; idx--) {
            int i = idx;
            int wi = ww[i];
            SquareMatrix<ModInt> m0 = mat.get(2 * i);
            SquareMatrix<ModInt> m1 = mat.get(2 * i + 1);
            if (!ini && wi > 0) {
                ww[i] = wi - 1;
                ini = true;
                int ii = i + 1;
                for (int k = 0; k < (1 << (ii - 1)); k++) {
